            if(role==="admin"?(!hasRole(user,"admin")||!hasCapability(user,"*")):!hasCapability(user,"classroom.control"))throw new Error(role==="admin"?"Enabled administrator profile required":"Permission required: classroom.control");
            ws.authUser=user;
